// Package carc is the Claim Adjustment Reason Code (CARC) list and the Code
// type that carries one CARC in an 835 or 837.
//
// The list is the entries table in this file: one row per code, with the
// code's description, status, and dates as its maintainer, the X12 Claim
// Adjustment Reason Code committee, publishes them. The rows come from
// backend/pkg/carc.json, the maintainer's list as fetched from
// x12.org/codes/claim-adjustment-reason-codes (the JSON's _meta gives the
// page and the date). After a refresh, make codes (tools/codegen) rewrites the
// rows between the table's two codegen marker comments from the JSON and
// changes nothing else. The rest of this file, and carc_test.go, are
// written by hand.
package carc

import "errors"

// Code is a Claim Adjustment Reason Code (CARC): the reason half of one
// CAS reason/amount/quantity triple on an 835 (CAS02/05/08/.../17).
//
// A Code is the code's text as the file carries it. The zero value, "", is
// an element not sent. A code that is not on the list is kept as it came,
// and Known reports that it is not listed; nothing here drops or rewrites a
// received value, so a file reads in and writes out byte for byte.
type Code string

// CodeNotSent is the zero value: the element was not sent.
const CodeNotSent Code = ""

// Entry is one code's row in the list. Every field but Short is the
// maintainer's own text. The JSON names are the ones /api/codes serves
// (docs/API.md), and the four fields after Status are left out of the JSON
// when empty.
type Entry struct {
	Code         string `json:"code"`                    // the code itself: "45", "P23"
	Short        string `json:"short"`                   // Description up to its first ". " or ";", or all of it
	Description  string `json:"description"`             // the full published text
	Status       string `json:"status"`                  // "current" or "deactivated"
	Start        string `json:"start,omitempty"`         // effective date
	Stop         string `json:"stop,omitempty"`          // deactivation date, "" if none
	LastModified string `json:"last_modified,omitempty"` // last change date, "" if never changed
	Notes        string `json:"notes,omitempty"`         // the maintainer's note, "" if none
}

// entries is the list, one row per code in backend/pkg/carc.json's order.
// make codes rewrites the rows between the two markers from that file, so a
// change belongs in the JSON, followed by make codes, not in a row here.
