// index finds each code's row in entries.
var index = func() map[Code]int {
	m := make(map[Code]int, len(entries))
	for i, e := range entries {
		m[Code(e.Code)] = i
	}
	return m
}()

// entry is the code's row; ok is false for a code not on the list.
func (c Code) entry() (Entry, bool) {
	i, ok := index[c]
	if !ok {
		return Entry{}, false
	}
	return entries[i], true
}

// String returns the code exactly as received.
func (c Code) String() string {
	return string(c)
}

// Known reports whether the code is on the list. An element not sent is not.
func (c Code) Known() bool {
	_, ok := index[c]
	return ok
}

// ShortDescription returns the code's first sentence or clause, or "" for a
// code not on the list.
func (c Code) ShortDescription() string {
	e, _ := c.entry()
	return e.Short
}

// Description returns the code's full maintainer-published description, or
// "" for a code not on the list.
func (c Code) Description() string {
	e, _ := c.entry()
	return e.Description
}

// Status returns the maintainer's status text for the code, or "" for a
// code not on the list.
func (c Code) Status() string {
	e, _ := c.entry()
	return e.Status
}

// Start returns the code's effective date, the maintainer's own text.
func (c Code) Start() string {
	e, _ := c.entry()
	return e.Start
}

// Stop returns the code's deactivation date, the maintainer's own text, or
// "" if the code has not been deactivated.
func (c Code) Stop() string {
	e, _ := c.entry()
	return e.Stop
}

// LastModified returns the code's last change date, the maintainer's own
// text, or "" if it has never changed.
func (c Code) LastModified() string {
	e, _ := c.entry()
	return e.LastModified
}

// Notes returns the maintainer's free-text note for the code, or "" if none.
func (c Code) Notes() string {
	e, _ := c.entry()
	return e.Notes
}

// Current reports whether the code's status is "current".
func (c Code) Current() bool {
	return c.Status() == "current"
}

// Parse reads one received CARC value: the text as it came, and an error
// when it is not empty and not on the list. The value is kept either way.
func Parse(code string) (Code, error) {
	c := Code(code)
	if code == "" || c.Known() {
		return c, nil
	}
	return c, errors.New("carc: parsing code: a value not on the list")
}

// Codes returns every code on the list, in the list's order.
func Codes() []Code {
	out := make([]Code, len(entries))
	for i, e := range entries {
		out[i] = Code(e.Code)
	}
	return out
}

// Entries returns a copy of the list, one Entry per code in the list's
// order, ready to marshal as JSON. Changing the copy does not change what
// the Code methods read.
func Entries() []Entry {
	out := make([]Entry, len(entries))
	copy(out, entries)
	return out
}
